shell_commands:
mkdir -p node_modules/.cache/ajv-probe && cat > node_modules/.cache/ajv-probe/probe.ts <<'EOF'
import {Ajv} from 'ajv';
const a = new Ajv({strict: false, validateFormats: false});
export const x = typeof a.compile;
EOF
cat > node_modules/.cache/ajv-probe/probe.js <<'EOF'
const path = require('path');
const ts = require(path.join(process.cwd(), 'node_modules', 'typescript'));
const opts = {
  strict: true, module: ts.ModuleKind.NodeNext, moduleResolution: ts.ModuleResolutionKind.NodeNext,
  esModuleInterop: true, skipLibCheck: true, target: ts.ScriptTarget.ES2022, noEmit: true,
  lib: ['lib.es2022.d.ts'], types: []
};
const file = path.join(process.cwd(), 'node_modules/.cache/ajv-probe/probe.ts');
const program = ts.createProgram({rootNames: [file], options: opts});
const diags = ts.getPreEmitDiagnostics(program);
for (const d of diags) console.log(d.file && d.file.fileName, d.code, ts.flattenDiagnosticMessageText(d.messageText, ' '));
console.log('diag count', diags.length);
EOF
node node_modules/.cache/ajv-probe/probe.js

cat > node_modules/.cache/ajv-probe/probe.cjs <<'EOF'
const path = require('path');
const ts = require(path.join(process.cwd(), 'node_modules', 'typescript'));
const tsconfigPath = path.join(process.cwd(), 'tsconfig.json');
const parsed = ts.getParsedCommandLineOfConfigFile(tsconfigPath, {noEmit: true}, {
  getCurrentDirectory: () => process.cwd(),
  useCaseSensitiveFileNames: true,
  readDirectory: (a,b,c,d,e) => [],
  fileExists: f => require('fs').existsSync(f),
  readFile: f => require('fs').readFileSync(f, 'utf8'),
  getCanonicalFileName: f => f,
  getNewLine: () => '\n',
  getCommonSourceDirectory: () => process.cwd(),
});
const opts = {...parsed.options, noEmit: true};
delete opts.skipLibCheck === undefined; // keep skipLibCheck as-is
const file = path.join(process.cwd(), 'node_modules/.cache/ajv-probe/probe.ts');
const program = ts.createProgram({rootNames: [file], options: opts});
const diags = ts.getPreEmitDiagnostics(program);
for (const d of diags) console.log(d.file && d.file.fileName, d.code, ts.flattenDiagnosticMessageText(d.messageText, ' ').slice(0,200));
console.log('diag count', diags.length);
EOF
node node_modules/.cache/ajv-probe/probe.cjs

cat > node_modules/.cache/ajv-probe/probe.cjs <<'EOF'
const path = require('path');
const ts = require(path.join(process.cwd(), 'node_modules', 'typescript'));
const roots = [
  'src/orchestration/tools/registry.ts',
  'src/orchestration/tools/registry.test.ts',
  'src/orchestration/tools/registry.acceptance.test.ts',
  'src/orchestration/chatOrchestrator.ts',
  'src/orchestration/chatOrchestrator.test.ts',
].map(f => path.join(process.cwd(), f));
const opts = {
  strict: true, module: ts.ModuleKind.NodeNext, moduleResolution: ts.ModuleResolutionKind.NodeNext,
  esModuleInterop: true, skipLibCheck: true, target: ts.ScriptTarget.ES2022, noEmit: true,
  lib: ['lib.es2022.d.ts'], isolatedModules: true, resolveJsonModule: true, baseUrl: process.cwd(),
};
const program = ts.createProgram({rootNames: roots, options: opts});
const diags = ts.getPreEmitDiagnostics(program).filter(d => d.file && d.file.fileName.includes('/src/'));
for (const d of diags) console.log(path.relative(process.cwd(), d.file.fileName), d.file.getLineAndCharacterOfPosition(d.start).line + 1, d.code, ts.flattenDiagnosticMessageText(d.messageText, ' ').slice(0,160));
console.log('src diag count', diags.length);
EOF
node node_modules/.cache/ajv-probe/probe.cjs

ls src/**/*.ts src/*.ts 2>/dev/null | wc -l ; cat > node_modules/.cache/ajv-probe/full.cjs <<'EOF'
const path = require('path');
const ts = require(path.join(process.cwd(), 'node_modules', 'typescript'));
const parsed = ts.getParsedCommandLineOfConfigFile(path.join(process.cwd(), 'tsconfig.json'), {noEmit: true}, {
  getCurrentDirectory: () => process.cwd(),
  useCaseSensitiveFileNames: true,
  readDirectory: (a,b,c,d,e) => ts.sys.readDirectory(a,b,c,d,e),
  fileExists: ts.sys.fileExists,
  readFile: ts.sys.readFile,
  getCanonicalFileName: ts.sys.useCaseSensitiveFileNames ? f => f : f => f.toLowerCase(),
  getNewLine: () => '\n',
  getCommonSourceDirectory: () => process.cwd(),
});
const program = ts.createProgram({rootNames: parsed.fileNames, options: {...parsed.options, noEmit: true}});
const diags = ts.getPreEmitDiagnostics(program);
const src = diags.filter(d => d.file && d.file.fileName.includes('/src/'));
for (const d of src) console.log(path.relative(process.cwd(), d.file.fileName) + ':' + (d.file.getLineAndCharacterOfPosition(d.start).line + 1) + ':' + (d.file.getLineAndCharacterOfPosition(d.start).character + 1), 'TS' + d.code, ts.flattenDiagnosticMessageText(d.messageText, ' ').slice(0, 180));
console.log('src diagnostics:', src.length, '| total:', diags.length);
EOF
timeout 300 node node_modules/.cache/ajv-probe/full.cjs
